-- Stem self-containment repair for JAMB 2024 English Language.
-- The student interface renders each question standalone (no passage pane), so the
-- source passage/book header shown above the question on myschool.ng must live
-- inside question_bank.question itself. This file re-inserts the headers that the
-- original import dropped (intro captured in a container variant the parser did
-- not handle at collection time).
-- Idempotent: every UPDATE matches the stable source marker embedded in the row.
-- Only question_bank.question changes; options and all other columns untouched.
SET NAMES utf8mb4;


UPDATE question_bank SET question = '<p><small>Source: JAMB 2024 English Language - Item 1 - Question 1</small></p><p><strong>JAMB 2024 English Language - Question 1</strong></p> From the novel; <strong>The Life Changer</strong><p>The following question is based on Khadija Abububakar Jalili&#39;s&nbsp;<strong><em>The Life Changer.</em></strong></p>\n\n<p>From Ummi&#39;s narration, what exactly is the &quot;Note&nbsp;of Salvation&quot;?</p>'
WHERE question LIKE '%Source: JAMB 2024 English Language - Item 1 - Question 1%'
  AND deleted = 0;

