UPDATE question_bank SET question = '<p><small>Source: JAMB 2024 English Language - Item 65 - Question 65</small></p><p><strong>JAMB 2024 English Language - Question 65</strong></p><p><strong>The passage below has gaps. Immediately following each gap, four options are provided. Choose the most appropriate option for each gap.&nbsp;</strong></p>\n\n<p>If one is looking for a particular book, he can either use the __6__ [A. reverse catalogue&nbsp;B. borrower&#39;s catalogue C. dictionary catalogue D. title catalogue] or the __7__ [A. author catalogue B. book catalogue C. title catalogue D. yearly catalogue] to locate the position of the book on the __8__ [A. table B. shelf C. cupboard D. desk] This can be done through the __9__ [A. borrower-mark B. reserve-mark C. call-mark D. year-mark] identification number. On the other hand, if the student has no particular book in mind, but wants to borrow any on a particular subject, say Mathematics, he can go to the __10__ [A. subject catalogue B. publisher catalogue C. reference catalogue D. cover catalogue]. There he will find the __11__ [A. book-card B. call-card C. author-card D. seller-card] of every book that deals with Mathematics as a subject. Apart from this, since all the shelves have instructions and numbers regarding the books on them, the person can read the __12__ [A. card&#39;s guide B. author&#39;s guide C. shelf-guides D. book-guides] and the book __13__ [A. acknowledgements B. commentaries C. titles D. spines] to get the book he wants. He can take the book to the __14__ [A. table B. reserve section C. sitting corner D. lending desk] where the library assistant removes the book card from the book __15__ [A. pocket B. title C. call-names D. reserve] and record the borrower&#39;s name on it.&nbsp;</p><p>Choose the option that best fills the gap labelled 6</p>'
WHERE question LIKE '%Source: JAMB 2024 English Language - Item 65 - Question 65%'
  AND deleted = 0;

